INSERT INTO pipeline_control.restaurant_review_policy(singleton,version,enabled,operator_id,batch_size,daily_limit) VALUES(true,7,true,'00000000-0000-0000-0000-000000000065',50,50);SET LOCAL ROLE service_role;SELECT set_config('request.jwt.claim.role','',true);SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);DO $test$ DECLARE p jsonb;BEGIN p:=public.restaurant_review_automation_manual('00000000-0000-0000-0000-000000000065','preview-run',NULL,NULL,NULL);UPDATE pipeline_control.restaurant_review_policy SET version=8;BEGIN PERFORM public.restaurant_review_automation_manual('00000000-0000-0000-0000-000000000065','run',p->>'version',p->>'previewHash',gen_random_uuid());RAISE EXCEPTION 'REVIEW_FIX_STALE_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'REVIEW_AUTOMATION_STALE' THEN RAISE;END IF;END;UPDATE pipeline_control.restaurant_review_policy SET version=7;p:=public.restaurant_review_automation_manual('00000000-0000-0000-0000-000000000065','preview-run',NULL,NULL,NULL);UPDATE public.restaurants SET phone='fixture changed' WHERE id='00000000-0000-0000-0000-000000000067';BEGIN PERFORM public.restaurant_review_automation_manual('00000000-0000-0000-0000-000000000065','run',p->>'version',p->>'previewHash',gen_random_uuid());RAISE EXCEPTION 'REVIEW_FIX_STALE_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'REVIEW_AUTOMATION_STALE' THEN RAISE;END IF;END;UPDATE pipeline_control.restaurant_review_policy SET enabled=false;BEGIN PERFORM public.restaurant_review_automation_manual('00000000-0000-0000-0000-000000000065','preview-run',NULL,NULL,NULL);RAISE EXCEPTION 'REVIEW_FIX_DISABLED_POLICY_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'REVIEW_AUTOMATION_STALE' THEN RAISE;END IF;END;IF EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_runs) THEN RAISE EXCEPTION 'REVIEW_FIX_STALE_WROTE';END IF;END $test$;ROLLBACK;